const items = $input.all();
if (items.length !== 1) throw new Error('failure_event_item_count_invalid');
const event = items[0]?.json;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const hasExecution = isObject(event?.execution);
const hasTrigger = isObject(event?.trigger);
if (!isObject(event) || !isObject(event.workflow) || hasExecution === hasTrigger) {
  throw new Error('failure_event_shape_invalid');
}
const boundedName = (value) => {
  if (typeof value !== 'string') return 'unavailable';
  const normalized = value
    .replace(/[\u0000-\u001f\u007f-\u009f]/gu, ' ')
    .replace(/\s+/gu, ' ')
    .trim();
  if (!normalized) return 'unavailable';
  return Array.from(normalized).slice(0, 40).join('');
};
const idValue = (value) => {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) return String(value);
  return '';
};
const workflowId = idValue(event.workflow.id);
const executionId = hasExecution ? idValue(event.execution.id) : '';
const validWorkflowId = /^[A-Za-z0-9_-]{1,64}$/.test(workflowId);
const validExecutionId = /^[1-9][0-9]{0,19}$/.test(executionId);
const failure = hasExecution ? event.execution : event.trigger;
const rawTimestamp = isObject(failure.error) ? failure.error.timestamp : undefined;
let failureTimestamp;
try {
  const timestampMs = typeof rawTimestamp === 'number' && Number.isFinite(rawTimestamp)
    ? rawTimestamp
    : typeof rawTimestamp === 'string' && rawTimestamp.length <= 64
      ? Date.parse(rawTimestamp)
      : Number.NaN;
  if (Number.isFinite(timestampMs)) failureTimestamp = new Date(timestampMs).toISOString();
} catch {}
const timestampLabel = failureTimestamp ? 'Failed at' : 'Detected at';
const timestamp = failureTimestamp ?? new Date().toISOString();
const notification = {
  topic: 'homelab',
  title: 'n8n workflow failed',
  priority: 3,
  message: [
    hasExecution ? 'Automatic workflow execution failed.' : 'Automatic workflow trigger failed.',
    `Workflow: ${boundedName(event.workflow.name)}`,
    `Node: ${hasExecution ? boundedName(event.execution.lastNodeExecuted) : 'trigger'}`,
    `Execution: ${validExecutionId ? executionId : 'unavailable'}`,
    `${timestampLabel}: ${timestamp}`,
  ].join('\n'),
};
if (validWorkflowId && validExecutionId) {
  notification.click = `https://n8n.lab.supermorphic.com/workflow/${workflowId}/executions/${executionId}`;
}
return [{ json: notification }];
